Конечно, вот пример кода на языке JavaScript, который посчитает числа Фибоначчие:

```
// Define the Fibonacci sequence function
function fibonacci(n) {
  // If the input is less than 2, return 0
  if (n < 2) return 0;
  // If the input is 2, return 1
  if (n === 2) return 1;
  // Calculate the nth Fibonacci number
  let fib = 0;
  let fibNext = 1;
  for (let i = 0; i < n; i++) {
    fib = fibNext;
    fibNext = fib + fibNext;
  }
  // Return the nth Fibonacci number
  return fib;
}

// Test the function
console.log(fibonacci(10)); // Output: 55
```

